def solve():
    solutions = []
    for a in range(0, 30):
        for b in range(0, 30):
            val = 2**a * 5**b + 625
            n_sq = int(val**0.5)
            if n_sq * n_sq == val:
                solutions.append((a, b, n_sq))
                solutions.append((a, b, -n_sq))
            elif (n_sq + 1) * (n_sq + 1) == val:
                solutions.append((a, b, n_sq + 1))
                solutions.append((a, b, -(n_sq + 1)))
    return solutions

print(solve())

def solve_large(limit):
