    for a in range(limit):
        for b in range(limit):
            val = 2**a * 5**b + 625
            n_sq = int(val**0.5)
            if n_sq * n_sq == val:
                solutions.append((a, b, n_sq))
                solutions.append((a, b, -n_sq))
            elif (n_sq + 1) * (n_sq + 1) == val:
